n = 11
edges = []
for i in range(n):
    for offset in [1, 2, 3]:
        j = (i + offset) % n
        u, v = min(i, j), max(i, j)
        if (u, v) not in edges:
            edges.append((u, v))

print("Number of edges:", len(edges))
kappa = vertex_connectivity(n, edges)
print("Vertex connectivity:", kappa)
print("Edges:", edges)
